1	import { describe, it, expect } from "vitest";
2	import { runScenario } from "./claim-office.js";
3	
4	describe("MHPCO Claim Office", () => {
5	  // --- Edge case: empty policy ---
6	  it("empty item list → premium 5 G (only the processing fee)", () => {
7	    const result = runScenario({
8	      customer: { yearsWithMHPCO: 0 },
9	      steps: [{ op: "quote", items: [] }],
10	    });
11	
12	    expect(result).toEqual({ results: [{ premium: 5 }] });
13	  });
14	
15	  // --- Base premiums per main item type (plus 5 G fee, first insurance 10 %) ---
16	  it.todo("single plain sword, new customer → base premium 100 G");
17	  it.todo("single plain amulet, new customer → base premium 60 G");
18	  it.todo("single plain staff, new customer → base premium 80 G");
19	  it.todo("single plain potion, new customer → base premium 40 G");
20	
21	  // --- Components ---
22	  it.todo("single rune → base premium 25 G");
23	  it.todo("single moonstone → base premium 25 G");
24	  it.todo("2 runes → 50 G base premium");
25	  it.todo("3 runes → 60 G base premium (block of 3 alike applies)");
26	  it.todo("4 runes → 100 G base premium (no block — block requires exactly 3)");
27	  it.todo("7 runes → 175 G base premium (no block for 7)");
28	
29	  // --- "Alike" components ---
30	  it.todo("2 runes + 1 moonstone → 75 G base premium (no block: different types)");
31	  it.todo("3 runes + 3 moonstones → 120 G base premium (two separate blocks)");
32	
33	  // --- Individual premium modifiers ---
34	  it.todo("cursed sword adds a 50 % risk surcharge on the item's base premium");
35	  it.todo("sword with enchantment 5 adds a 30 % high-enchantment surcharge");
36	  it.todo("sword with enchantment 4 → no high-enchantment surcharge");
37	  it.todo("cursed sword with enchantment 5 → both surcharges apply");
38	  it.todo("customer with exactly 2 years with MHPCO → 20 % loyalty discount applies");
39	  it.todo("customer with 1 year with MHPCO → no loyalty discount");
40	  it.todo("first quote in a scenario carries the 10 % initial assessment surcharge");
41	  it.todo("second quote in a scenario receives the 15 % follow-up contract discount");
42	  it.todo("first insurance surcharge applies to every quote's items regardless of customer history");
43	
44	  // --- Modifier scope on multi-item policies ---
45	  it.todo(
46	    "cursed sword + plain amulet → policy base 160 G, curse adds 50 G (item-scoped) → 210 G before further modifiers and fee",
47	  );
48	  it.todo("policy-wide modifiers (loyalty, first insurance, follow-up) apply to the policy base premium");
49	  it.todo("the 5 G processing fee is added at the very end");
50	
51	  // --- Rounding in the MHPCO's favor ---
52	  it.todo("a premium calculation that yields 197.5 G → final premium 198 G (rounded up)");
53	  it.todo("a payout calculation that yields 350.5 G → final payout 350 G (rounded down)");
54	  it.todo("intermediate amounts are kept as fractions; only the final amount is rounded");
55	
56	  // --- Standard claim reimbursement ---
57	  it.todo("regular sword (steel, enchantment 3), damage 500 G → payout 400 G");
58	  it.todo("damage to a rune (value 250 G), damage 200 G → payout 100 G (no special clause)");
59	
60	  // --- Enchantment threshold vs. dragon material ---
61	  it.todo("dragon-material sword, enchantment 8, damage 1000 G → payout 400 G");
62	  it.todo("dragon-material sword, enchantment 9, damage 1000 G → payout 400 G (50 % rule wins, then deductible)");
63	  it.todo("dragon-material sword, enchantment 5, damage 800 G → payout 700 G (full reimbursement, then deductible)");
64	  it.todo("steel sword, enchantment 9, damage 1000 G → payout 400 G (50 % first, then deductible)");
65	
66	  // --- Deductible per damage event ---
67	  it.todo("dragon attack damages sword (500 G) and amulet (300 G) → payout 600 G (deductible once per damaged item)");
68	
69	  // --- Insurance sum and cap ---
70	  it.todo("a policy covering a sword and an amulet → insurance sum 1600 G, cap 3200 G");
71	  it.todo("a cursed sword → cap 2000 G (premium modifiers do not raise the cap)");
72	  it.todo("a policy covering a sword and 3 runes → insurance sum 1750 G (block discount affects premium only)");
73	  it.todo("a policy covering two swords → insurance sum 2000 G, cap 4000 G");
74	
75	  // --- Cap exhaustion across successive claims ---
76	  it.todo("sword (cap 2000 G), first claim of 1500 G → payout 1400 G, remainingCap 600 G");
77	  it.todo("sword (cap 2000 G), second claim of 1500 G → payout 600 G, remainingCap 0 G");
78	
79	  // --- Multiple items of the same type ---
80	  it.todo("two sword damage entries against a policy with two swords → each entry gets its own deductible");
81	  it.todo("more damage entries of a type than the policy covers → error (claim rejected)");
82	
83	  // --- Error cases ---
84	  it.todo("quote with an unknown item type (e.g. broomstick) → error");
85	  it.todo("claim referencing an item not part of the policy (amulet damaged, only sword insured) → error");
86	  it.todo("claim referencing a damage entry with an unknown item type → error");
87	  it.todo("claim with a damage entry of amount -200 → error");
88	
89	  // --- Integration examples ---
90	  it.todo("newcomer with a cursed sword (0 years, no previous contract) → premium 165 G");
91	  it.todo("long-standing customer's second contract with a cursed sword (3 years, enchantment 7) → premium 160 G");
92	
93	  // --- CLI-level scenario ---
94	  it.todo("schema example scenario → results array with a quote premium and a claim payout/remainingCap");
95	});
